import { create } from "zustand";
import { getMediaDuration, processMediaAssets } from "@/media/processing";
import type { ProcessedMediaAsset } from "@/media/processing";
import type { MediaAsset } from "@/media/types";
import { IndexedDBAdapter } from "@/services/storage/indexeddb-adapter";
import { generateUUID } from "@/utils/id";

/** Bundled effects live in public/sounds; manifest.json is generated by scripts/generate-sound-manifest.ts */
const BUNDLED_SOUNDS_PATH = "/sounds";

export interface SoundItem {
	id: string;
	name: string;
	fileName: string;
	duration: number;
	size: number;
	url: string;
	isUser: boolean;
}

interface BundledSoundEntry {
	file: string;
	name: string;
	duration: number;
	size: number;
}

interface StoredUserSound {
	id: string;
	fileName: string;
	duration: number;
	blob: Blob;
}

const userSoundsDb = new IndexedDBAdapter<StoredUserSound>({
	dbName: "opencut-sound-library",
	storeName: "sounds",
});

function stripExtension(fileName: string): string {
	return fileName.replace(/\.[^.]+$/, "");
}

function toUserSoundItem(stored: StoredUserSound): SoundItem {
	return {
		id: stored.id,
		name: stripExtension(stored.fileName),
		fileName: stored.fileName,
		duration: stored.duration,
		size: stored.blob.size,
		url: URL.createObjectURL(stored.blob),
		isUser: true,
	};
}

async function loadBundledSounds(): Promise<SoundItem[]> {
	const response = await fetch(`${BUNDLED_SOUNDS_PATH}/manifest.json`);
	if (!response.ok) return [];
	const entries: BundledSoundEntry[] = await response.json();
	return entries.map((entry) => ({
		id: `bundled:${entry.file}`,
		name: entry.name,
		fileName: entry.file,
		duration: entry.duration,
		size: entry.size,
		url: `${BUNDLED_SOUNDS_PATH}/${encodeURIComponent(entry.file)}`,
		isUser: false,
	}));
}

interface SoundLibraryStore {
	sounds: SoundItem[];
	status: "idle" | "loading" | "ready";
	load: () => Promise<void>;
	addFiles: (files: File[]) => Promise<number>;
	remove: (id: string) => Promise<void>;
}

export const useSoundLibraryStore = create<SoundLibraryStore>()(
	(set, get) => ({
		sounds: [],
		status: "idle",
		load: async () => {
			if (get().status !== "idle") return;
			set({ status: "loading" });
			const [bundled, stored] = await Promise.all([
				loadBundledSounds().catch(() => []),
				userSoundsDb.getAll().catch(() => []),
			]);
			set({
				sounds: [...stored.map(toUserSoundItem), ...bundled],
				status: "ready",
			});
		},
		addFiles: async (files) => {
			const added: SoundItem[] = [];
			for (const file of files) {
				if (!file.type.startsWith("audio/")) continue;
				const duration = await getMediaDuration({ file }).catch(() => 0);
				const stored: StoredUserSound = {
					id: `user:${generateUUID()}`,
					fileName: file.name,
					duration,
					blob: file,
				};
				await userSoundsDb.set({ key: stored.id, value: stored });
				added.push(toUserSoundItem(stored));
			}
			set({ sounds: [...added, ...get().sounds] });
			return added.length;
		},
		remove: async (id) => {
			const sound = get().sounds.find((item) => item.id === id);
			if (!sound?.isUser) return;
			await userSoundsDb.remove(id);
			URL.revokeObjectURL(sound.url);
			set({ sounds: get().sounds.filter((item) => item.id !== id) });
		},
	}),
);

/**
 * Library sounds are not project media, so a drop first imports the file into
 * the project. A sound already imported (same file name and size) is reused.
 */
export async function importSoundAsMedia({
	sound,
	projectId,
	mediaAssets,
	addMediaAsset,
}: {
	sound: Pick<SoundItem, "url" | "fileName" | "size">;
	projectId: string;
	mediaAssets: MediaAsset[];
	addMediaAsset: (args: {
		projectId: string;
		asset: ProcessedMediaAsset;
	}) => Promise<MediaAsset | null>;
}): Promise<MediaAsset | null> {
	const existing = mediaAssets.find(
		(asset) =>
			!asset.ephemeral &&
			asset.name === sound.fileName &&
			asset.file.size === sound.size,
	);
	if (existing) return existing;

	const blob = await (await fetch(sound.url)).blob();
	const file = new File([blob], sound.fileName, { type: blob.type });
	const [processed] = await processMediaAssets({ files: [file] });
	if (!processed) return null;
	return addMediaAsset({ projectId, asset: processed });
}
